package com.guardianxr.ar;
import android.app.*;import android.os.*;import android.graphics.Color;import android.content.*;import android.widget.*;
public class VerifyActivity extends Activity{@Override protected void attachBaseContext(Context n){super.attachBaseContext(LocaleUtil.apply(n));}public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(30,50,30,30);l.setBackgroundColor(0xff07101c);TextView h=new TextView(this);h.setText(R.string.verify_certificate);h.setTextColor(Color.WHITE);h.setTextSize(22);l.addView(h);EditText e=new EditText(this);e.setHint(R.string.enter_cert_id);e.setTextColor(Color.WHITE);e.setHintTextColor(0xff9eacc2);String pre=getIntent().getStringExtra("cert_id");if(pre!=null)e.setText(pre);l.addView(e);TextView out=new TextView(this);out.setTextColor(Color.WHITE);out.setTextSize(18);Button v=new Button(this);v.setText(R.string.verify_offline);v.setOnClickListener(x->{String id=e.getText().toString().trim();String data=getSharedPreferences("guardianxr",MODE_PRIVATE).getString("cert_"+id,null);out.setText(data==null?getString(R.string.not_verified):getString(R.string.verified)+" ✓\n"+data);});l.addView(v);l.addView(out);setContentView(l);}}
